/**
 * Nutrition — the USDA reference set (W4-3 N3, design §3.1/§4.7).
 *
 * A curated set of global staple ingredients from USDA FoodData Central
 * (Foundation + SR Legacy only; Branded excluded), generated by
 * `scripts/nutrition-usda-reference.mjs` from USDA's bulk downloads and
 * shipped as app data. Every entry is read through the strict N1 parser, so
 * a malformed generated row drops here rather than reaching a screen — and
 * the test suite asserts nothing drops.
 *
 * The licence gate lives here too, reused from the evidence registry rather
 * than reinvented: a provenance kind resolves to a registry source, and the
 * source must be registered AND pass `productUseAllowed`. Anything else —
 * an unregistered source, a permission-gated one — fails closed. That is
 * what keeps IFCT/INDB values out of the product until written permission
 * exists: they cannot pass this gate today.
 */

import { CATALOG } from "../vitalis/evidence/catalog";
import { productUseAllowed } from "../vitalis/evidence/licensing";
import {
  USDA_REFERENCE_FOODS_RAW,
  USDA_REFERENCE_FINGERPRINT,
  USDA_REFERENCE_RETRIEVED_ON,
  USDA_REFERENCE_VERSION,
} from "./data/usdaReferenceData";
import { parseFoodList } from "./parse";
import type { Food, FoodProvenance, FoodProvenanceKind } from "./types";

export { USDA_REFERENCE_FINGERPRINT, USDA_REFERENCE_RETRIEVED_ON, USDA_REFERENCE_VERSION };

/** The reference foods, parsed. Stable order: the generator's curation. */
export const USDA_REFERENCE_FOODS: readonly Food[] = parseFoodList(USDA_REFERENCE_FOODS_RAW);

export function findUsdaReference(id: string): Food | null {
  return USDA_REFERENCE_FOODS.find((f) => f.id === id) ?? null;
}

/**
 * The FoodData Central releases this set was generated from, keyed by the
 * data type each food's provenance carries — as recorded in the generated
 * data's header. FoodData Central publishes no single version number
 * spanning both datasets, so the honest stamp names the release of the
 * dataset the food actually came from, never an invented umbrella version.
 */
const USDA_RELEASE_BY_DATA_TYPE: Readonly<Record<string, string>> = {
  Foundation: "2025-04-24 release",
  "SR Legacy": "2018-04 release",
};

/**
 * The data-version line shown wherever a reference food's provenance is
 * displayed: the source, the release its values came from, and the date
 * Bloom retrieved the set — e.g. "USDA FoodData Central · Foundation ·
 * 2025-04-24 release · retrieved 2026-11-16". Null for anything that is
 * not a USDA reference food: a user's own food has no dataset version to
 * stamp, and its badge already says whose value it is.
 */
export function usdaDataStamp(food: Food): string | null {
  if (food.provenance.kind !== "usda") return null;
  const dataType = food.provenance.dataType;
  const release = dataType ? USDA_RELEASE_BY_DATA_TYPE[dataType] : undefined;
  return [
    "USDA FoodData Central",
    ...(dataType ? [release ? `${dataType} · ${release}` : dataType] : []),
    `retrieved ${USDA_REFERENCE_RETRIEVED_ON}`,
  ].join(" · ");
}

/**
 * The dataset-level version line (audit #29): the one place a user or
 * support can name exactly which dataset the app's reference food values
 * came from — the dataset, its licence, when Bloom retrieved it, and the
 * shipped set's fingerprint in short form (the full fingerprint is the
 * USDA_REFERENCE_VERSION record, check-verified against the data by
 * `seed:usda:check`). Built only from the generator-stamped record, so
 * the line can never claim a version the data does not carry.
 */
export function usdaDatasetVersionLine(): string {
  const v = USDA_REFERENCE_VERSION;
  return [
    `${v.dataset} reference set`,
    v.licence,
    `retrieved ${v.retrievedOn}`,
    `fingerprint ${v.fingerprint.slice(0, 8)}`,
  ].join(" · ");
}

/**
 * Name search over the reference set, for the N4 add-food flow (which ranks
 * the user's own foods above these, per design §3.1). Every query token must
 * appear in the food's name; results rank a name that starts with the query
 * first, then the earliest match, then the shorter name — deterministic, no
 * scoring state.
 */
export function searchUsdaReference(query: string, limit = 20): Food[] {
  const tokens = query
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter(Boolean);
  const firstToken = tokens[0];
  if (firstToken === undefined) return [];
  const phrase = tokens.join(" ");
  const scored: { food: Food; score: number }[] = [];
  for (const food of USDA_REFERENCE_FOODS) {
    const name = food.name.toLowerCase();
    if (!tokens.every((t) => name.includes(t))) continue;
    const score =
      (name.startsWith(phrase) ? 0 : 1) * 100_000 + name.indexOf(firstToken) * 100 + name.length;
    scored.push({ food, score });
  }
  return scored
    .sort((a, b) => a.score - b.score)
    .slice(0, limit)
    .map((s) => s.food);
}

/* ------------------------------ licence gate ------------------------------ */

/**
 * Provenance kind → evidence-registry source id. Kinds with no registry
 * source (user_entered is the user's own data, not a reference set; off is
 * not yet registered) have no entry and fail the gate by construction.
 */
const REGISTRY_SOURCE_BY_KIND: Partial<Record<FoodProvenanceKind, string>> = {
  usda: "usda-fooddata-central",
  cofid: "uk-cofid-2021",
  afcd: "au-afcd-release-3",
  cnf: "ca-cnf-2026",
  ifct: "icmr-nin-ifct-2017",
};

/**
 * May data from this registry source ship in the product? True only when the
 * source is registered, its row says so, and its licence independently
 * derives the same answer via `productUseAllowed`. Fails closed on an
 * unknown id — an unregistered source (INDB today) is not a permissive one.
 */
export function registrySourceGate(sourceId: string): boolean {
  const source = CATALOG.sources.find((s) => s.id === sourceId);
  if (!source) return false;
  return source.productUseAllowed && productUseAllowed(source.license);
}

/** May a food with this provenance ship as reference data? */
export function referenceProvenanceGate(provenance: FoodProvenance): boolean {
  const sourceId = REGISTRY_SOURCE_BY_KIND[provenance.kind];
  if (!sourceId) return false;
  return registrySourceGate(sourceId);
}
